      "notasPedagogicas": {
        "diretrizes": "Integração de duas vozes independentes: melodia cantabile no topo e linha de baixo no polegar (p). (Versão Simplificada com andamento ou densidade reduzida).",
        "amortecimento": "Encerramento conjunto no c.8: melodia e baixo soam por 3 pulsos e entram em pausa simultânea no pulso 4.0. O som do baixo é sustentado pela ressonância livre da corda solta; o polegar se afasta após o ataque (não apoia na corda para sustentar).",
        "voicings": "Baixos em Dó (5/3), Fá (4/3) e Sol (6/3) contra melodia em 1ª e 2ª cordas.",
        "entregaU2": null
      }
