        "diretrizes": "Arranjo completo em 3 camadas: melodia cantabile (m/a), preenchimento harmônico interno (i) e baixo sustentado (p). Digitação recomendada no compasso 8: melodia com m, voz interna com i. (Versão Simplificada com andamento ou densidade reduzida).",
        "amortecimento": "No c.8, pausa conjunta de todas as 3 vozes no pulso 4.0. Amortecimento ativo por alívio suave de pressão na mão esquerda sem retirar o contato com a corda.",
        "voicings": "Acordes de C, F e G com voz interna na 3ª corda (G solta).",
        "entregaU2": "A entrega oficial da Unidade 2 exige a execução integral dos 16 compassos da peça (forma de 8 compassos com repetição completa AABB, totalizando entre 69 e 77 segundos a 50–56 BPM), com confirmação explícita na avaliação para liberação de avanço."
